<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/Core/Database.php';
require_once dirname(__DIR__,2).'/app/Core/Auth.php';
require_once dirname(__DIR__,2).'/app/Services/QuestionBankService.php';
use App\Core\Auth; use App\Core\Database; use App\Services\QuestionBankService;
Auth::requireAdmin('../login.php'); $db=Database::connection(); $svc=new QuestionBankService($db);
function e(string $v): string { return htmlspecialchars($v,ENT_QUOTES,'UTF-8'); }
$id=(int)($_GET['id']??$_POST['id']??0); $error=null;
$question=['category_id'=>'','question'=>'','type'=>'qcm','difficulty'=>1,'lesson'=>'','topic'=>'','explanation'=>'','active'=>1]; $answers=[['answer'=>'','is_correct'=>1],['answer'=>'','is_correct'=>0],['answer'=>'','is_correct'=>0],['answer'=>'','is_correct'=>0]];
if($id){$s=$db->prepare('SELECT * FROM questions WHERE id=:id');$s->execute(['id'=>$id]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row){http_response_code(404);exit('Question introuvable.');}$question=$row;$a=$db->prepare('SELECT answer,is_correct FROM question_answers WHERE question_id=:id ORDER BY display_order,id');$a->execute(['id'=>$id]);$answers=$a->fetchAll(PDO::FETCH_ASSOC) ?: $answers;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Auth::validateCsrf($_POST['csrf_token']??null))$error='Jeton de sécurité invalide.';
 else try{
  $postedAnswers=[]; foreach((array)($_POST['answer']??[]) as $i=>$text){$postedAnswers[]=['answer'=>$text,'is_correct'=>isset($_POST['correct'][$i])?1:0];}
  $data=['category_id'=>$_POST['category_id']??null,'question'=>$_POST['question']??'','type'=>$_POST['type']??'qcm','difficulty'=>$_POST['difficulty']??1,'lesson'=>$_POST['lesson']??'','topic'=>$_POST['topic']??'','explanation'=>$_POST['explanation']??'','active'=>isset($_POST['active'])?1:0,'answers'=>$postedAnswers];
  $saved=$svc->save($data,$id?:null); header('Location: questions.php?message=saved&id='.$saved); exit;
 }catch(Throwable $ex){$error=$ex->getMessage();$question=array_merge($question,$_POST);$answers=$postedAnswers??$answers;}
}
$categories=$db->query('SELECT c.id,c.name,m.title module_title FROM categories c JOIN modules m ON m.id=c.module_id WHERE c.active=1 AND m.active=1 ORDER BY m.display_order,c.display_order,c.id')->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $id?'Modifier':'Ajouter' ?> une question</title><link rel="stylesheet" href="../assets/css/app.css"></head><body><main class="admin-main" style="max-width:1100px;margin:auto"><div class="page-head"><div><span class="eyebrow">❓ BANQUE DE QUESTIONS</span><h1><?= $id?'Modifier la question #'.$id:'Ajouter une question' ?></h1></div><a class="btn btn-secondary" href="questions.php">Retour</a></div><?php if($error):?><div class="card" style="padding:1rem;margin-bottom:1rem;border-color:#fb7185"><?=e($error)?></div><?php endif;?><form method="post" class="card" style="padding:1.25rem"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem"><div class="form-group"><label class="label">Catégorie</label><select class="input" name="category_id" required><option value="">Choisir</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=(string)$question['category_id']===(string)$c['id']?'selected':''?>><?=e($c['module_title'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="label">Type</label><select class="input" name="type"><?php foreach(['qcm','true_false','multiple','short'] as $t):?><option <?=$question['type']===$t?'selected':''?>><?=$t?></option><?php endforeach;?></select></div><div class="form-group"><label class="label">Difficulté</label><input class="input" type="number" min="1" max="5" name="difficulty" value="<?=e((string)$question['difficulty'])?>"></div></div><div class="form-group"><label class="label">Question</label><textarea class="input" name="question" rows="3" required><?=e((string)$question['question'])?></textarea></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:1rem"><div class="form-group"><label class="label">Leçon</label><input class="input" name="lesson" value="<?=e((string)$question['lesson'])?>"></div><div class="form-group"><label class="label">Sujet</label><input class="input" name="topic" value="<?=e((string)$question['topic'])?>"></div></div><div class="form-group"><label class="label">Explication pédagogique</label><textarea class="input" name="explanation" rows="3"><?=e((string)$question['explanation'])?></textarea></div><h2>Réponses</h2><p><small>QCM : 1 bonne réponse. Multiple : plusieurs possibles. Vrai/Faux : 2 réponses. Short : variantes acceptées.</small></p><div id="answers"><?php for($i=0;$i<max(6,count($answers));$i++):$a=$answers[$i]??['answer'=>'','is_correct'=>0];?><div style="display:grid;grid-template-columns:auto 1fr;gap:.75rem;align-items:center;margin:.5rem 0"><label><input type="checkbox" name="correct[<?=$i?>]" value="1" <?=!empty($a['is_correct'])?'checked':''?>> Correcte</label><input class="input" name="answer[<?=$i?>]" value="<?=e((string)$a['answer'])?>" placeholder="Réponse <?=($i+1)?>"></div><?php endfor;?></div><label style="display:flex;gap:.5rem;align-items:center;margin:1rem 0"><input type="checkbox" name="active" value="1" <?=!empty($question['active'])?'checked':''?>> Question active</label><button class="btn btn-primary" type="submit">Enregistrer</button></form></main></body></html>